"""Build semantic, crawlable HTML. Standard library only, no install required."""
from pathlib import Path
import json,os,html,shutil
root=Path(__file__).resolve().parents[1];out=root/'dist'
cfg=json.loads((root/'src/config.json').read_text()); images={i['slug']:i for i in json.loads((root/'src/images.json').read_text())}
ready=os.environ.get('PUBLISH_READY',str(cfg['publishReady'])).lower()=='true'
origin=os.environ.get('SITE_URL','').rstrip('/')
if ready and not origin: raise SystemExit('Set SITE_URL to the actual public origin before enabling indexing.')
base=os.environ.get('BASE_PATH','').rstrip('/')
if base and not base.startswith('/'):base='/'+base
pages={};e=html.escape
# All internal links resolve at a custom domain or a GitHub project subpath.
def url(path=''):return base+'/'+path.lstrip('/')
def link(path,label,cls='text-link'):return f'<a class="{cls}" href="{url(path)}">{label} <span aria-hidden="true">↗</span></a>'
def photo(slug,cls='',eager=False,sizes='(max-width: 760px) 90vw, 45vw'):
 i=images[slug];src=url(f'assets/{slug}-{min(i["widths"],key=lambda x:abs(x-960))}.webp')
 srcset=', '.join(f'{url(f"assets/{slug}-{w}.webp")} {w}w' for w in i['widths'])
 return f'<img class="{cls}" src="{src}" srcset="{srcset}" sizes="{sizes}" width="{i["width"]}" height="{i["height"]}" alt="{e(i["alt"])}" loading="{"eager" if eager else "lazy"}" decoding="async"'+(' fetchpriority="high"' if eager else '')+'>'
def header(active):
 nav=[('portfolio/','The work'),('experience/','Experience'),('investment/','Investment'),('about/','About')]
 return ('<div class="preview-note">DESIGN PREVIEW · Session details and pricing for review</div>' if not ready else '')+f'''<a class="skip" href="#main">Skip to content</a><header class="site-header"><a href="{url()}" class="wordmark" aria-label="Trevor Adair Photography home"><span>TREVOR ADAIR</span><small>PHOTOGRAPHY</small></a><button class="menu-toggle" aria-expanded="false" aria-controls="navigation">Menu</button><nav class="nav" id="navigation" aria-label="Main navigation">'''+''.join(f'<a href="{url(p)}"'+(' aria-current="page"' if active==p else '')+f'>{label}</a>' for p,label in nav)+link('contact/','Let’s make memories','button')+'</nav></header>'
def footer():return f'''<footer class="footer"><div class="footer-main"><div class="footer-brand"><a href="{url()}" class="wordmark"><span>TREVOR ADAIR</span><small>PHOTOGRAPHY</small></a><p>Portraits, people, and the places that bring us together.<br>Based in Utah County. Serving Provo, Orem, and beyond.</p></div><div class="footer-links"><span class="eyebrow">Explore</span><a href="{url('portfolio/')}">Selected work</a><a href="{url('sessions/families/')}">Families</a><a href="{url('sessions/couples/')}">Couples & proposals</a><a href="{url('sessions/seniors/')}">Seniors & graduates</a><a href="{url('sessions/portraits/')}">Portraits & missionaries</a><a href="{url('sessions/events/')}">Events</a><a href="{url('journal/')}">The journal</a></div><div class="footer-links"><span class="eyebrow">Say hello</span><a href="mailto:{cfg['email']}">{cfg['email']}</a><a href="tel:{cfg['phone']}">801 · 837 · 9308</a><a href="{cfg['instagram']}" target="_blank" rel="noopener noreferrer">Instagram ↗</a><a href="{cfg['facebook']}" target="_blank" rel="noopener noreferrer">Facebook ↗</a><a href="{url('contact/')}">Plan your session</a></div></div><div class="footer-bottom"><span>© 2026 Trevor Adair Photography</span><span>PROVO · OREM · UTAH COUNTY</span><a href="{url('privacy/')}">Privacy</a></div></footer>'''
def cta():return '<section class="cta"><div><span class="eyebrow">Your next chapter</span><h2>Let’s make something<br><em>worth keeping.</em></h2></div>'+link('contact/','Tell me what you’re imagining','button')+'</section>'
def page(path,title,desc,body,hero='mountain-engagement'):
 canonical=origin+url(path) if origin else ''
 schema={'@context':'https://schema.org','@type':'ProfessionalService','name':cfg['name'],'description':'Portrait, family, couples, senior, missionary and event photography in Provo, Orem and Utah County.','email':cfg['email'],'telephone':cfg['phone'],'areaServed':[{'@type':'City','name':n} for n in ['Provo','Orem']]+[{'@type':'AdministrativeArea','name':'Utah County'}],'sameAs':[cfg['instagram'],cfg['facebook']]}
 if origin:schema.update(url=origin+url(),image=origin+url(f'assets/{hero}-960.webp'))
 head=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{e(title)}</title><meta name="description" content="{e(desc)}"><meta name="theme-color" content="#30362b"><meta name="robots" content="{'index,follow,max-image-preview:large' if ready and path!='404.html' else 'noindex,follow'}"><meta property="og:type" content="website"><meta property="og:site_name" content="Trevor Adair Photography"><meta property="og:title" content="{e(title)}"><meta property="og:description" content="{e(desc)}"><meta name="twitter:card" content="summary_large_image">'''
 if origin:head+=f'<link rel="canonical" href="{canonical}"><meta property="og:url" content="{canonical}"><meta property="og:image" content="{origin+url(f"assets/{hero}-960.webp")}"><meta property="og:image:alt" content="{e(images[hero]["alt"])}">'
 head+=f'<link rel="icon" href="{url("assets/favicon.svg")}" type="image/svg+xml"><link rel="stylesheet" href="{url("assets/fonts.css")}"><link rel="stylesheet" href="{url("assets/style.css")}"><script>document.documentElement.classList.add("js")</script><script type="application/ld+json">{json.dumps(schema)}</script><script src="{url("assets/app.js")}" defer></script></head><body>'
 file=out/(path if path.endswith('.html') else path+'index.html');file.parent.mkdir(parents=True,exist_ok=True)
 file.write_text(head+header(path)+'<main id="main">'+body+'</main>'+footer()+'</body></html>')
 pages[path]={'title':title,'description':desc}
def intro(kicker,title,desc=''):return f'<section class="page-intro"><p class="breadcrumb"><a href="{url()}">Home</a> / {kicker}</p><span class="eyebrow">{kicker}</span><h1>{title}</h1><p>{desc}</p></section>'
def faq(items):return '<div class="faq">'+''.join(f'<details><summary>{q}</summary><p>{a}</p></details>' for q,a in items)+'</div>'
def gallery(slugs,filters=False):
 content=''
 if filters:content='<div class="gallery-toolbar" role="group" aria-label="Filter photographs">'+''.join(f'<button class="filter" data-filter="{v}" aria-pressed="{str(v=="all").lower()}">{l}</button>' for v,l in [('all','All work'),('couples','Couples'),('families','Families'),('seniors','Seniors'),('portraits','Portraits'),('events','Events')])+'</div><p class="gallery-count" role="status">'+str(len(slugs))+' photographs · All work</p>'
 content+='<div class="gallery">'
 for slug in slugs:
  i=images[slug];land=i['width']>i['height']
  content+=f'<figure class="{"landscape" if land else "portrait"}" data-category="{i["category"]}"><button data-full="{url(f"assets/{slug}-{max(i['widths'])}.webp")}" aria-label="Enlarge: {e(i["alt"])}">'+photo(slug,sizes='(max-width:760px) 90vw, 65vw' if land else '(max-width:760px) 45vw, 30vw')+f'</button><figcaption>{i["alt"]}</figcaption></figure>'
 return content+'''</div><dialog class="lightbox" aria-label="Photograph viewer"><div class="lightbox-bar"><span class="lightbox-counter" aria-live="polite"></span><div><button data-prev aria-label="Previous photograph">← Previous</button><button data-next aria-label="Next photograph">Next →</button><button data-close aria-label="Close photograph viewer">Close ×</button></div></div><img alt=""><p class="lightbox-caption" aria-live="polite"></p></dialog>'''
def process():return '''<div class="steps"><div class="step"><span>01 /</span><h3>Start with your story.</h3><p>Tell me who you’re celebrating, what you have in mind, and when. We’ll work out the kind of session that fits.</p></div><div class="step"><span>02 /</span><h3>Make room to be you.</h3><p>We’ll choose a setting and plan the details. During your session, I’ll give you direction and leave room for the moments between poses.</p></div><div class="step"><span>03 /</span><h3>Keep this chapter close.</h3><p>Your photographs will be thoughtfully edited into a gallery you can revisit, share, and make part of your everyday life.</p></div></div>'''
articles=[('what-to-wear','What to wear for family photos','A simple approach to colors, texture, and feeling like yourselves.','family-under-tree'),('graduation-photo-planning','Your graduation photo checklist','Caps, gowns, locations, and the little details that make it yours.','graduation-celebration'),('planning-a-proposal','Planning a proposal, quietly','A thoughtful plan for keeping the surprise and capturing the moment.','autumn-proposal')]
def journal_cards():return '<div class="journal-grid">'+''.join(f'<a class="journal-card" href="{url("journal/"+slug+"/")}">'+photo(im,sizes='(max-width:760px) 90vw, 30vw')+f'<span class="eyebrow">The field notes · 0{i+1}</span><h3>{title}</h3><p>{desc}</p><span class="text-link">Read the guide ↗</span></a>' for i,(slug,title,desc,im) in enumerate(articles))+'</div>'
home='''<section class="hero"><div class="hero-top"><span class="eyebrow">Utah County portrait & lifestyle photographer</span><span class="edition">People. Place. Connection.</span></div><div class="hero-layout"><div class="hero-copy"><h1>A little of<br>your life.<br><em>Held still.</em></h1><p>Honest photographs of the people you love and the chapters you’ll want to remember. Made here in Utah.</p>'''+link('portfolio/','Explore the photographs')+'</div><figure class="hero-main">'+photo('mountain-engagement',eager=True,sizes='(max-width:760px) 80vw, (max-width:1100px) 45vw, 38vw')+'</figure><figure class="hero-side">'+photo('quiet-embrace',sizes='20vw')+'<figcaption>The big feelings.<br>The smallest gestures.</figcaption></figure></div><div class="hero-bottom"><span>Couples · Families · Portraits · Milestones</span><a href="#discover">Discover the stories ↓</a><span>Based in Provo / Orem, Utah</span></div></section>'
home+='''<section class="intro" id="discover"><span class="eyebrow">For the way life feels</span><h2>The years move quickly.<br><em>Let’s keep a little of this one.</em></h2><p>The way they fit into your arms. The breath before a yes. That smile after everything you worked for. I photograph the familiar and the once-in-a-lifetime, with room for your personality in every frame.</p></section>'''
home+='<section class="section services"><div class="section-head"><div><span class="eyebrow">A chapter for everyone</span><h2>What brings<br><em>you here?</em></h2></div><p>Come as you are. Bring your people.<br>We’ll make photographs that feel like a part of your life.</p></div><div class="service-grid">'
for n,(slug,title,sub,desc,img) in enumerate([('couples','Together, always.','Couples & proposals','For the beginning of something beautiful, or the life you’ve already built together.','lakeside-couple'),('families','Your kind of love.','Families','The personalities, the closeness, and a little of the beautiful chaos.','family-under-tree'),('seniors','What comes next.','Seniors & graduates','A new chapter deserves more than a quick photo in a cap and gown.','graduation-celebration')]):
 home+=f'<a class="service-card" href="{url("sessions/"+slug+"/")}"><div class="image-window">'+photo(img,sizes='(max-width:760px) 90vw, 30vw')+f'</div><div class="meta"><h3>{title}</h3><span aria-hidden="true">↗</span></div><span class="eyebrow">0{n+1} / {sub}</span><p>{desc}</p></a>'
home+='</div><div class="service-extra">'+link('sessions/portraits/','Portraits & missionaries')+link('sessions/events/','Events & celebrations')+'</div></section>'
home+='<section class="wide-story">'+photo('sunset-couple',sizes='100vw')+'<div class="story-copy"><span class="eyebrow">The moment before everything changes</span><h2>You’ll remember<br><em>how it felt.</em></h2>'+link('sessions/couples/','Couples & proposal photography')+'</div></section>'
home+='<section class="section split"><div class="split-image">'+photo('garden-portrait')+'<p class="image-caption">From the portrait collection · Photograph by Trevor Adair</p></div><div class="split-copy"><span class="eyebrow">The person behind the photographs</span><h2>A love for people.<br><em>An eye for the light.</em></h2><p>I’m Trevor, a photographer based in Utah County. My work moves between portraits, families, couples, and the natural world—always with an eye for the details that make a photograph feel alive.</p><p>From a quiet trail to a room full of celebration, I want to make images you recognize yourself in.</p><div class="signature">Trevor Adair</div>'+link('about/','A little more about me')+'</div></section>'
if cfg['testimonialApproved'] or not ready:home+='<section class="quote"><span class="eyebrow">Words to keep</span><blockquote>“Quite literally the perfect<br>photographer for us.”</blockquote><span class="eyebrow">Xandra Black</span>'+('' if cfg['testimonialApproved'] else '<p class="placeholder">Placeholder testimonial · awaiting approval</p>')+'</section>'
home+='<section class="section"><div class="section-head"><div><span class="eyebrow">A thoughtful, easy experience</span><h2>Good photographs start<br><em>with feeling comfortable.</em></h2></div>'+link('experience/','The experience')+'</div>'+process()+'</section>'
home+='<section class="section services"><div class="section-head"><div><span class="eyebrow">A few useful field notes</span><h2>Before the<br><em>camera comes out.</em></h2></div>'+link('journal/','Explore the journal')+'</div>'+journal_cards()+'</section>'+cta()
page('','Utah County Photographer | Trevor Adair Photography','Portrait, family, couples, senior and missionary photography in Provo, Orem and Utah County. Explore Trevor Adair’s work and plan your session.',home)
page('portfolio/','Photography Portfolio | Trevor Adair Photography','Explore Trevor Adair’s couples, family, senior, portrait and event photography. Browse a collection of personal moments and Utah landscapes.',intro('Selected work','Life, in <em>good company.</em>','A collection of people, connections, and new beginnings. Choose a chapter, or stay for all of them.')+'<section class="section small-section">'+gallery(['mountain-engagement','quiet-embrace','engagement-ring','family-under-tree','graduation-celebration','garden-portrait','sunset-couple','window-light-portrait','lakeside-family','missionary-portrait','stone-doorway-portrait','lakeside-couple','meadow-proposal','graduation-river','autumn-proposal','family-hillside','culinary-event'],True)+'</section>'+cta())
services={
'families':dict(label='Family photography',title='Your people.<br><em>Your everything.</em>',desc='Family photographs in Provo, Orem, and Utah County—with room for little personalities, big laughs, and all the ways you belong together.',image='family-under-tree',price=280,terms=['A 60-minute session','Up to 6 immediate family members','A curated gallery of 40+ edited images'],copy='There’s room for everyone to be themselves.',text='We’ll make the portrait you want to hang on the wall, and leave time for the moments you couldn’t plan: small hands reaching for yours, siblings making each other laugh, the way you all lean together. Tell me about your family’s ages and energy so we can plan a session around them.',photos=['family-under-tree','family-hillside','lakeside-family'],faq=[('What if my children don’t want to sit still?','They don’t need to sit still the whole time. We can build in movement, little breaks, and time together. Bring a snack and a favorite small toy if that helps.'),('Can we include extended family?','Yes—tell me your group size and the combinations you’d like photographed. I’ll put together a quote and a plan with enough time for everyone.'),('Where should our session take place?','Start with somewhere that feels like your family: a familiar outdoor setting, a quiet trail, or an open space. We’ll discuss light, access, season, and comfort before choosing a location.')]),
'couples':dict(label='Couples & proposal photography',title='This is<br><em>your kind of love.</em>',desc='Engagements, anniversaries, surprise proposals, and the days you simply want to remember. Couples photography in Utah County and beyond.',image='mountain-engagement',price=380,terms=['A 60-minute couples session','One location with room to explore','A curated gallery of 40+ edited images'],copy='A beautiful setting. A real connection.',text='You bring the connection; I’ll help with the rest. We’ll find a setting that suits you, move at an easy pace, and make space for both guided portraits and the little moments that happen naturally. Planning a proposal? We’ll talk through the timing, a discreet meeting point, and what happens after the yes.',photos=['quiet-embrace','engagement-ring','autumn-proposal','meadow-proposal','lakeside-couple','mountain-engagement','sunset-couple'],faq=[('Can you help photograph a surprise proposal?','Yes. Proposal sessions start at $350. We’ll coordinate your plan privately, including the location, timing, and a signal so I know when the moment is coming. Photography coverage and any extra time will be confirmed before booking.'),('Do we have to know how to pose?','No. I’ll offer direction, simple movement, and room to interact. You don’t need to arrive with a practiced pose.'),('Are decorations included?','Proposal pricing is for photography. Flowers, arches, candles, location fees, and other setup arrangements are separate and should be discussed while planning.')]),
'seniors':dict(label='Senior & graduation photography',title='Here’s to<br><em>what comes next.</em>',desc='Senior and graduation portraits for students in Provo, Orem, and Utah County. Celebrate the work, the growth, and everything waiting ahead.',image='graduation-celebration',price=230,terms=['A 60-minute session','Up to 2 outfits, including your cap & gown','A curated gallery of 30+ edited images'],copy='More than the cap and gown.',text='Bring the outfit you feel best in, the things that matter to you, and a little excitement for what’s next. We can make classic graduation portraits and images that feel more personal—outdoors, with architectural texture, or in a setting connected to your story.',photos=['graduation-celebration','stone-doorway-portrait','graduation-river'],faq=[('Can we plan photos around BYU or UVU graduation?','Yes. Tell me your graduation date and when you need the photographs for announcements. We’ll agree on a session date and delivery timeline before you book.'),('Can I bring a friend or family member?','You’re welcome to bring someone to help with outfits and cheer you on. If you want a shared photo session, tell me how many graduates will be participating so I can quote the right amount of time.'),('What should I bring?','Bring your cap and gown, cords or stole, comfortable shoes for walking, and any meaningful small props. Check the graduation photo checklist in the journal for more ideas.')]),
'portraits':dict(label='Portrait & missionary photography',title='A portrait.<br><em>Entirely you.</em>',desc='Individual and missionary portraits in Provo, Orem, and Utah County. Thoughtful light, personal settings, and photographs with a sense of who you are.',image='window-light-portrait',price=220,terms=['A 45-minute individual session','One location & up to 2 outfits','A curated gallery of 25+ edited images'],copy='A little personality goes a long way.',text='A portrait can be quiet, expressive, celebratory, or all of those things. Whether you’re preparing to serve a mission, updating your personal photographs, or making something creative, we’ll plan the light and setting around the feeling you want.',photos=['missionary-portrait','window-light-portrait','garden-portrait'],faq=[('Do you photograph missionaries?','Yes. Bring the clothing and any meaningful items you would like included. We can make a mix of traditional portraits and relaxed photographs to share with family and friends.'),('Can we create something more artistic?','Absolutely. Tell me about the mood, location, or idea you have in mind. We’ll discuss what’s practical and build a session around it.'),('Are studio fees included?','The starting session price is for an agreed outdoor location. Any studio rental, venue access, or special production costs will be discussed separately before booking.')]),
'events':dict(label='Event photography',title='Be there.<br><em>I’ll remember it.</em>',desc='Photography for celebrations, culinary gatherings, and community events in Utah County. The people, the atmosphere, and the details you worked so hard to bring together.',image='culinary-event',price=None,terms=['Coverage tailored to your event','People, atmosphere & thoughtful details','A gallery shaped around your priorities'],copy='The story is in the details.',text='A beautifully plated dish. A familiar face across the room. The pause before a toast. Event photographs should bring back the feeling of being there. Tell me about your occasion, your timeline, and how you plan to use the images so I can recommend the right coverage.',photos=['culinary-event'],faq=[('How is event photography priced?','Each event is quoted based on duration, location, guest count, and the intended use of the images. Share your timeline and priorities for a tailored quote.'),('Can I provide a list of important photographs?','Please do. Let me know about key people, scheduled moments, sponsors, details, and anything that can’t be missed.'),('Do you cover school dances and group portraits?','Yes—send the group size, date, location, and the combinations you’d like. Group photo coverage is quoted separately to allow enough time for everyone.')])}
for slug,s in services.items():
 if slug in cfg['prices']:s['price']=cfg['prices'][slug]
 if slug=='couples':s['faq']=[(q,a.replace('$350', '$'+str(cfg['prices']['proposals']))) for q,a in s['faq']]
 body=f'<section class="service-hero"><div><span class="eyebrow">{s["label"]} · Utah County</span><h1>{s["title"]}</h1><p>{s["desc"]}</p><p class="price-inline">'+(f'From ${s["price"]}' if s['price'] else 'A quote made for your occasion')+'</p>'+link('contact/?session='+slug,'Let’s plan your session','button')+'</div>'+photo(s['image'],eager=True)+'</section>'
 body+='<section class="details-band">'+''.join(f'<div><h2>0{i+1} / {t.split(" ")[0]}</h2><p>{t}</p></div>' for i,t in enumerate(s['terms']))+'</section>'
 body+='<section class="intro"><span class="eyebrow">Made personal</span><h2>'+s['copy']+'</h2><p>'+s['text']+'</p></section><section class="section small-section">'+gallery(s['photos'])+'</section><section class="section services"><span class="eyebrow center">Before we meet</span><h2 class="center">A few good questions.</h2>'+faq(s['faq'])+'</section>'+cta()
 page('sessions/'+slug+'/',s['label']+' in Provo & Orem | Trevor Adair',s['desc'],body,s['image'])
pricebody=intro('The investment','Beautiful photographs.<br><em>Clear starting points.</em>','Choose the chapter you’re in. Every session starts with a conversation about your people, your plans, and the photographs you want to come home with.')+'<section class="section small-section"><div class="price-grid">'
for slug in ['families','couples','seniors','portraits']:
 s=services[slug];pricebody+=f'<article class="price-card {"featured" if slug=="families" else ""}"><span class="eyebrow">Utah County sessions</span><h2>{s["label"].replace(" photography","")}</h2><span class="eyebrow">Starting at</span><p class="amount">${s["price"]}</p><ul>'+''.join('<li>'+t+'</li>' for t in s['terms'])+'</ul>'+link('contact/?session='+slug,'Ask about this session','button')+'</article>'
pricebody+='<article class="price-card"><span class="eyebrow">The big question</span><h2>Surprise proposals</h2><span class="eyebrow">Starting at</span><p class="amount">$350</p><ul><li>Private planning conversation</li><li>Up to 45 minutes of photography</li><li>Proposal moment & portraits afterward</li><li>25+ edited images</li></ul>'+link('contact/?session=proposals','Plan the surprise','button')+'</article><article class="price-card"><span class="eyebrow">Something a little different</span><h2>Events & groups</h2><p class="amount">Let’s talk.</p><ul><li>Event coverage</li><li>Extended families</li><li>School dance groups</li><li>Creative or commercial projects</li></ul>'+link('contact/?session=events','Request a quote','button')+'</article></div><p class="fine-print">Starting prices cover the session described. Additional people, travel, studio rentals, permits, rush delivery, and special requests are quoted separately. Your total, delivery schedule, and booking terms will be confirmed before you reserve.</p>'+('' if ready else '<p class="fine-print">Review note: these are proposed packages and market-based starting prices. Session length, image counts, and booking terms need Trevor’s final approval.</p>')+'</section>'
pricebody+='<section class="section services"><h2 class="center">The details, <em>made simple.</em></h2>'+faq([('What is included in a session?','The session plan above includes photography and a curated edited digital gallery. We’ll confirm the final scope, personal printing permission, and delivery date in your booking details.'),('How do I reserve a date?','Start with an inquiry. We’ll confirm availability, location, and your session plan, then I’ll send the booking steps. Sending an inquiry does not reserve a date or charge you.'),('When will my photographs be ready?','We’ll agree on the delivery timeline before you book. If you have an announcement deadline or a time-sensitive event, include that in your inquiry.'),('What if the weather changes?','We’ll stay in touch about the forecast and talk through a different time, location, or date if conditions don’t suit your session. Rescheduling terms will be confirmed when booking.')])+'</section>'+cta()
pricebody=pricebody.replace('$350', '$'+str(cfg['prices']['proposals']))
page('investment/','Photography Session Pricing | Trevor Adair Photography','Explore starting prices for family, couples, proposal, senior and portrait photography in Utah County. Find your session and request availability.',pricebody)
page('experience/','The Photography Experience | Trevor Adair Photography','From your first inquiry to your finished gallery, explore a thoughtful approach to portrait sessions in Provo, Orem and Utah County.',intro('The experience','Less performing.<br><em>More being here.</em>','You don’t need to arrive knowing what to do with your hands. We’ll make a plan, find good light, and give you space to settle in.')+'<section class="section small-section">'+process()+'</section><section class="section split services"><div class="split-copy"><span class="eyebrow">Before your session</span><h2>A little planning.<br><em>A lot more ease.</em></h2><p>Tell me what you love, what you’re hoping for, and what makes you nervous. We’ll talk about the setting, outfits, who’s coming, and any details that deserve extra care.</p><p>Comfort matters. If you need an accessible location, shorter walking distances, breaks, or a quieter setting, let me know as we plan.</p>'+link('journal/what-to-wear/','What to wear')+'</div><div class="split-image">'+photo('stone-doorway-portrait')+'</div></section><section class="intro"><span class="eyebrow">During your session</span><h2>Direction when you need it.<br><em>Space when you don’t.</em></h2><p>We’ll make a mix of composed portraits and natural interactions. There’s time to try an idea, change the angle, take a breath, and notice the things that make your people yours.</p></section>'+cta())
page('about/','Meet Trevor Adair | Utah County Photographer','Meet Trevor Adair, a Utah County photographer creating portraits, family, couples, senior and event photographs in Provo, Orem and beyond.',intro('Behind the camera','Hi, I’m Trevor.<br><em>I notice the little things.</em>','A photographer in Utah County, drawn to people, the outdoors, and the moments where the two meet.')+'<section class="section split small-section"><div class="about-statement">Good light.<br>Real connection.<br>A reason to<br><em>remember.</em><span>TREVOR ADAIR</span></div><div class="split-copy"><span class="eyebrow">A little about me</span><h2>People and places.<br><em>Both worth a closer look.</em></h2><p>I’m based in the Provo–Orem area, where I photograph families, couples, seniors, missionaries, and events. I also photograph wildlife and nature, and that love of noticing the world carries into my portrait work.</p><p>I’m a student at Brigham Young University. Outside the classroom, photography gives me a different way to be curious: about a person’s story, a fleeting expression, or the way the light changes a familiar place.</p><p>My aim is simple: photographs that hold onto something personal. I’d love to hear what that looks like for you.</p>'+link('contact/','Start a conversation')+'</div></section><section class="section"><div class="section-head"><div><span class="eyebrow">A few things I’m drawn to</span><h2>Connection. Color.<br><em>A sense of place.</em></h2></div></div>'+gallery(['window-light-portrait','garden-portrait','missionary-portrait'])+'</section>'+cta())
contact=intro('Let’s make memories','Tell me about<br><em>your next chapter.</em>','A few details are all we need to get started. Share what you’re imagining, and we’ll talk about availability, the right setting, and a session that fits.')+f'''<section class="contact-layout"><aside class="contact-details">{photo('quiet-embrace')}<span class="eyebrow">Prefer to say hello directly?</span><a href="mailto:{cfg['email']}">{cfg['email']}</a><a href="tel:{cfg['phone']}">801 · 837 · 9308</a><p>Based in Utah County<br>Provo · Orem · surrounding communities</p><p>Instagram: <a href="{cfg['instagram']}">@trevoradair.portraits ↗</a></p></aside><div class="contact-form"><form id="inquiry-form" data-email="{cfg['email']}"><div class="form-grid"><div class="field"><label for="name">Your name *</label><input id="name" name="name" autocomplete="name" maxlength="100" required></div><div class="field"><label for="email">Email address *</label><input id="email" name="email" type="email" autocomplete="email" maxlength="200" required></div><div class="field"><label for="phone">Phone (optional)</label><input id="phone" name="phone" type="tel" autocomplete="tel" maxlength="40"></div><div class="field"><label for="session">What are we celebrating? *</label><select id="session" name="session" required><option value="">Choose your session</option value="families">Family</option><option value="couples">Couples / engagements</option><option value="proposals">Surprise proposal</option><option value="seniors">Senior / graduation</option><option value="portraits">Portrait / missionary</option><option value="events">Event / group</option><option value="other">Something else</option></select></div><div class="field"><label for="date">Preferred date (optional)</label><input id="date" name="date" type="date"></div><div class="field"><label for="location">Location ideas (optional)</label><input id="location" name="location" maxlength="200" placeholder="Somewhere in Utah County…"></div><div class="field full"><label for="message">Tell me a little about your plans *</label><textarea id="message" name="message" minlength="10" maxlength="4000" required placeholder="Who’s coming, what you’re imagining, and anything you’d like me to know."></textarea></div></div><p class="form-note">This prepares an email for you to review and send. Your details stay on this page until you choose to email them. No date is reserved by preparing an inquiry.</p><button type="submit" class="button">Prepare my inquiry <span aria-hidden="true">↗</span></button><p id="form-status" class="form-status" role="status"></p></form><noscript><p class="no-js-note">To inquire, email <a href="mailto:{cfg['email']}">{cfg['email']}</a> with your session type, preferred date, and plans. The email draft builder needs JavaScript.</p></noscript><section id="inquiry-output" class="inquiry-output" hidden><h2 tabindex="-1">Your inquiry is ready.</h2><div class="inquiry-actions"><a class="button" data-email-draft>Open in my email app ↗</a><button class="button outline" data-copy>Copy message</button></div><label for="draft-text">Your email draft</label><textarea id="draft-text" readonly></textarea><p id="copy-status" role="status"></p></section></div></section>'''
page('contact/','Contact Trevor Adair | Plan Your Utah Photo Session','Inquire about a family, couples, proposal, senior, missionary or event session in Utah County. Email Trevor Adair or prepare your session inquiry.',contact,'quiet-embrace')
page('journal/','Photo Session Planning Guides | Trevor Adair Photography','Practical guides to planning family photographs, graduation portraits and a surprise proposal. Explore field notes from Trevor Adair Photography.',intro('The journal','A little preparation.<br><em>A more meaningful photograph.</em>','Ideas for feeling comfortable, making a plan, and bringing something personal to your session.')+'<section class="section small-section">'+journal_cards()+'</section>'+cta())
article_bodies={
'what-to-wear':'''<p>The best outfit is one you can move in and recognize yourself wearing. Start with the setting and the season, then build a small palette that gives everyone room to look like themselves.</p><h2>Choose a palette, not a uniform.</h2><p>Pick two or three related colors and add neutrals. Cream, soft blue, and muted green can sit comfortably together outdoors. Warm brown, ivory, and denim are another easy starting point. You don’t need every person in the same shirt.</p><h2>Mix texture with quiet patterns.</h2><p>Knitwear, linen, cotton, and a little layering add variety without fighting for attention. One subtle pattern can work beautifully; several bold patterns together can pull your eye away from faces. Lay the outfits beside each other before deciding.</p><h2>Let comfort do some of the work.</h2><p>Choose clothes that fit well while sitting, walking, and picking up a child. Have everyone try on the full outfit, including shoes. Bring practical walking shoes if the location involves a trail, even if you change before the photographs.</p><h2>Plan for little people.</h2><p>Children are more comfortable in familiar clothes than in something stiff or itchy. Bring an extra layer, a small snack, and a backup outfit when it makes sense. A relaxed child matters more than a perfectly tucked shirt.</p><div class="callout">Try this: take a quick phone photo of all the outfits laid out together. If one item dominates the whole picture, simplify that piece.</div><h2>Keep the location in mind.</h2><p>For a green outdoor setting, a little contrast helps the family stand out. Against stone or architecture, softer colors and texture can keep the image from feeling too busy. We’ll talk about your location and the light before your session.</p>''',
'graduation-photo-planning':'''<p>Graduation photographs mark more than the end of a semester. They’re a way to remember the work that got you here and the person you’ve become. A little preparation makes room to enjoy the occasion.</p><h2>Start with when you need the images.</h2><p>If you want photographs for announcements, invitations, or a celebration, work backward from that date. Tell me your deadline before booking so we can agree on a realistic session and delivery schedule.</p><h2>Pack a small session bag.</h2><ul><li>Your cap and gown, steamed or neatly pressed.</li><li>Any cords, stole, tassel, or other graduation details.</li><li>An outfit you feel good wearing without the gown.</li><li>Comfortable shoes for moving between spots.</li><li>Water, a comb or brush, and a few pins for the cap.</li><li>A meaningful prop if there’s something you want to include.</li></ul><h2>Choose a place with a reason.</h2><p>A campus can tell one part of your story; a favorite outdoor setting can tell another. For BYU and UVU graduates, we can discuss a campus-inspired session or a different setting in Provo or Orem. Any location access or photography requirements should be checked before finalizing the plan.</p><h2>Make time for the individual.</h2><p>Plan for photographs in the gown and photographs without it. We can create a classic portrait, a little movement, and something that speaks to your personality. You don’t need to know a collection of poses beforehand.</p><div class="callout">Avoid bringing loose confetti into outdoor spaces. A cap in the air, a big laugh, or a little movement makes a celebration without leaving anything behind.</div><h2>Bring someone who makes you comfortable.</h2><p>A friend or family member can help carry your things and bring a little extra confidence. If they’re also joining the photographs, mention that in your inquiry so we can plan the time.</p>''',
'planning-a-proposal':'''<p>A surprise proposal is a lot to hold in your head. The aim of the photography plan is to make one part feel easy: knowing the moment will be documented while you stay with the person in front of you.</p><h2>Begin with your partner.</h2><p>Think about whether they would enjoy a public moment or a quieter setting. The location should fit the two of you. A meaningful place can matter more than an elaborate setup.</p><h2>Talk through the exact spot.</h2><p>We’ll discuss where you’ll arrive, where you’ll stand, and how I can see the moment without interrupting it. Share photographs or a simple description of the location, and have an alternative if the space is busy.</p><h2>Leave a little room in the timeline.</h2><p>Allow for traffic, a longer walk, or a pause along the way. Good communication helps more than a minute-by-minute script. We’ll agree on a signal and how to reach each other before you arrive.</p><h2>Separate the photography from the setup.</h2><p>If you want flowers, candles, an arch, or a picnic, plan who is arranging those details. Photography coverage doesn’t automatically include decorations or setup. Discuss any venue access, cleanup, and extra costs in advance.</p><h2>Stay in the moment afterward.</h2><p>You don’t have to turn immediately toward the camera. Take the time you need together. Afterward, we can make a few portraits, photograph the ring, and remember the setting where it happened.</p><div class="callout">Have a weather plan, a private way to communicate, and a pocket that keeps the ring secure. Then leave space for the moment to be its own.</div>'''}
for slug,title,desc,im in articles:
 body=intro('Field notes · Session planning',title,desc)+'<article class="article">'+photo(im,eager=True,sizes='(max-width:760px) 90vw, 770px')+article_bodies[slug]+link('contact/','Let’s plan your session')+'</article>'+cta()
 page('journal/'+slug+'/',title+' | Trevor Adair Photography',desc,body,im)
page('privacy/','Privacy | Trevor Adair Photography','How this website handles your visit and the information you choose to share when making a photography inquiry.',intro('Privacy','Your details,<br><em>handled thoughtfully.</em>')+f'''<article class="article"><h2>When you browse</h2><p>This website does not include advertising trackers, analytics scripts, or embedded social-media feeds. Its photographs, fonts, styles, and scripts are served with the website. The hosting provider may process standard technical request information to deliver and secure the site.</p><h2>When you inquire</h2><p>The inquiry builder prepares text locally in your browser. It does not submit your details to a server or save them in browser storage. When you choose “Open in my email app,” your email app receives the draft. You decide whether to send it. Your email provider’s privacy practices apply.</p><h2>Information you send</h2><p>Information you email to Trevor is used to respond to your inquiry and discuss photography services. Only include details needed to plan your session. For questions about your information, contact <a href="mailto:{cfg['email']}">{cfg['email']}</a>.</p><h2>Other websites</h2><p>Links to Instagram and Facebook take you to those services. Their privacy practices apply when you visit them.</p><p>Last updated November 4, 2026.</p></article>''')
